INSERT INTO authorities (section_code, authority_name) VALUES ('10.06', 'An Inter-Ministerial Working Group (IMWG) in DGFT');
INSERT INTO authorities (section_code, authority_name) VALUES ('10.06', 'Chairman/DGFT');
INSERT INTO authorities (section_code, authority_name) VALUES ('10.06', 'SCOMET Cell in DGFT');
INSERT INTO timelines (section_code, timeline_text) VALUES ('10.06', 'Timeline for comments/NOC by IMWG members: The members of IMWG will
endeavour to furnish their written comments/views/no objection to DGFT
within 30 days from the date of forwarding of online application by DGFT
(Hqrs.).');
INSERT INTO timelines (section_code, timeline_text) VALUES ('10.06', 'If no comments/views/no objection is received within the stipulated
period, the cases will be placed before IMWG for taking a decision as deemed
appropriate.');
INSERT INTO timelines (section_code, timeline_text) VALUES ('10.06', 'Where a case has been
deferred in the IMWG meeting and subsequently comments/views/NOC(s)
are received from all concerned agencies with no divergence in views,
authorisation shall be issued with the approval of Chairman, IMWG or any
officer nominated by Chairman/DGFT (not below the rank of Deputy Director
General of Foreign Trade/Under Secretary) and such cases shall be brought
before IMWG in its subsequent meeting for approval on ex-post facto
basis.');
