INSERT INTO rules (rule_id, section_code, rule_text, rule_type, trigger_text, condition_text, validation_text, action_text, exception_text, output_text) VALUES ('CH10-SEC10_16-R031', '10.16', 'The applicant exporter declares that the items that are intended to be
