INSERT INTO rules (rule_id, section_code, rule_text, rule_type, trigger_text, condition_text, validation_text, action_text, exception_text, output_text) VALUES ('CH10-SEC10_16-R032', '10.16', 'The applicant exporter declares that subsequent to issue of export
authorisation, if the licensee has been notified in writing by DGFT or if
